// ---------------------------------------------------------------------------
// Reading a business's own public profile out of a page's structured data.
//
// Booking platforms publish schema.org `LocalBusiness` JSON-LD on every profile
// page, because it is how they rank in Google. That makes the same parser work
// for any platform that does it — verified on Bokadirekt, which is the dominant
// Swedish salon/clinic/wellness platform and therefore the biggest vertical we
// have. It is NOT universal: TheFork and Matchi publish none, so treat a miss as
// normal and fall back to the heuristic scrapers.
//
// This is the low-cost half of "let owners keep what they already wrote". No API
// key, no vendor relationship, no cache — just the page they already have.
//
// Pure: no network. Callers fetch through Convex (safeFetchPinned) and pass HTML.
// ---------------------------------------------------------------------------

/** A review a business earned somewhere else. `sourceLabel` and `sourceUrl` are
 *  REQUIRED, not decorative: republishing someone else's reviews unattributed is
 *  both legally doubtful and duplicate content, so the shape makes attribution
 *  impossible to forget. */
export type ExternalReview = {
  author: string;
  /** 1-5. Platforms that use another range are normalised by the parser. */
  rating: number | null;
  text: string;
  /** ISO date when the platform published it, when it says. */
  publishedAt: string | null;
  sourceLabel: string;
  sourceUrl: string;
};

export type ExternalRating = {
  /** Mean score, on the platform's own `bestRating` scale. */
  value: number;
  best: number;
  count: number;
  sourceLabel: string;
  sourceUrl: string;
};

export type ExternalProfile = {
  name: string | null;
  /** Street, postal code and locality as the platform holds them — a PROPOSAL
   *  for the owner to confirm, never a silent overwrite. A gym's API said
   *  "Kiviks Torg 1, 27731" while the gym's own page said "Torget 1, 277 30". */
  street: string | null;
  postalCode: string | null;
  city: string | null;
  phone: string | null;
  email: string | null;
  lat: number | null;
  lng: number | null;
  description: string | null;
  rating: ExternalRating | null;
  reviews: ExternalReview[];
};

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

function str(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const t = v.trim();
  return t === "" ? null : t;
}

function numOf(v: unknown): number | null {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "string") {
    const n = Number(v.replace(",", "."));
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

/** Every JSON-LD object on a page, flattened through `@graph` and arrays. */
export function jsonLdBlocks(html: string): Record<string, unknown>[] {
  const out: Record<string, unknown>[] = [];
  const re = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(html)) !== null) {
    let parsed: unknown;
    try {
      parsed = JSON.parse(m[1]);
    } catch {
      continue; // a malformed block on someone else's page is not our problem
    }
    const queue = Array.isArray(parsed) ? [...parsed] : [parsed];
    while (queue.length) {
      const item = queue.shift();
      if (!isRecord(item)) continue;
      if (Array.isArray(item["@graph"])) queue.push(...item["@graph"]);
      out.push(item);
    }
  }
  return out;
}

const BUSINESS_TYPES = new Set([
  "localbusiness",
  "healthandbeautybusiness",
  "beautysalon",
  "hairsalon",
  "daysspa",
  "healthclub",
  "sportsactivitylocation",
  "gym",
  "restaurant",
  "medicalbusiness",
  "dentist",
  "physiotherapy",
  "professionalservice",
  "store",
  "organization",
]);

function isBusiness(item: Record<string, unknown>): boolean {
  const t = item["@type"];
  const types = (Array.isArray(t) ? t : [t]).filter((x): x is string => typeof x === "string");
  return types.some((x) => BUSINESS_TYPES.has(x.toLowerCase()));
}

function parseReview(
  raw: unknown,
  sourceLabel: string,
  sourceUrl: string,
): ExternalReview | null {
  if (!isRecord(raw)) return null;
  const text = str(raw.reviewBody);
  const author = isRecord(raw.author) ? str(raw.author.name) : str(raw.author);
  if (!text || !author) return null;

  const ratingObj = isRecord(raw.reviewRating) ? raw.reviewRating : null;
  const value = ratingObj ? numOf(ratingObj.ratingValue) : null;
  const best = ratingObj ? numOf(ratingObj.bestRating) : null;
  // Normalise to a 5-point scale so a 10-point platform does not render as 9/5.
  const rating =
    value !== null && best !== null && best > 0 ? Math.round((value / best) * 50) / 10 : value;

  return {
    author,
    rating,
    text,
    publishedAt: str(raw.datePublished),
    sourceLabel,
    sourceUrl,
  };
}

/**
 * Read a business profile out of a page's structured data.
 *
 * `sourceLabel` is what a visitor sees beside a quoted review ("Bokadirekt") and
 * `sourceUrl` is where it links. Both are required because the reviews are not
 * ours to reprint silently.
 *
 * Returns null when the page publishes no business object — which is the common
 * case, not an error.
 */
export function parseLocalBusinessProfile(
  html: string,
  sourceLabel: string,
  sourceUrl: string,
): ExternalProfile | null {
  const business = jsonLdBlocks(html).find(isBusiness);
  if (!business) return null;

  const address = isRecord(business.address) ? business.address : null;
  const geo = isRecord(business.geo) ? business.geo : null;
  const agg = isRecord(business.aggregateRating) ? business.aggregateRating : null;

  const ratingValue = agg ? numOf(agg.ratingValue) : null;
  const ratingCount = agg ? (numOf(agg.reviewCount) ?? numOf(agg.ratingCount)) : null;
  const ratingBest = agg ? numOf(agg.bestRating) : null;

  const reviews = (Array.isArray(business.review) ? business.review : [])
    .map((r) => parseReview(r, sourceLabel, sourceUrl))
    .filter((r): r is ExternalReview => r !== null);

  return {
    name: str(business.name),
    street: address ? str(address.streetAddress) : null,
    // Swedish postal codes are published both as "195 30" and "19530".
    postalCode: address ? str(address.postalCode) : null,
    city: address ? str(address.addressLocality) : null,
    phone: str(business.telephone),
    email: str(business.email),
    lat: geo ? numOf(geo.latitude) : null,
    lng: geo ? numOf(geo.longitude) : null,
    description: str(business.description),
    rating:
      ratingValue !== null && ratingCount !== null
        ? {
            value: ratingValue,
            best: ratingBest ?? 5,
            count: ratingCount,
            sourceLabel,
            sourceUrl,
          }
        : null,
    reviews,
  };
}

/**
 * Reviews worth seeding: substantial enough to read, and positive enough that an
 * owner would have chosen them.
 *
 * We are not laundering a business's reputation — a one-star review stays on the
 * platform where it belongs, and the aggregate rating we show alongside is the
 * honest number including it. This only decides which quotes to PROPOSE; the
 * owner picks.
 */
export function seedableReviews(profile: ExternalProfile, max = 3): ExternalReview[] {
  return profile.reviews
    .filter((r) => r.text.length >= 40 && (r.rating === null || r.rating >= 4))
    .slice(0, max);
}
